import yaml
import os
import xmltodict
import re

from pathlib import Path
from auto_config.generator.utils.utils import merge_dictionaries
from auto_config.generator.utils.get_bts_config import Config

class Model:
    RMODS_YAML = Path(os.path.abspath(__file__)).parents[2] / "config" / "rmods.yaml"
    IPHY_XML = Path(os.path.abspath(__file__)).parents[1] / "config" / "iphy_db.xml"
    BBMODS_SMODS_YAML = Path(os.path.abspath(__file__)).parents[2] / "config" / "bbmods_smods.yaml"
    PROFILES_PATH = Path(os.path.abspath(__file__)).parents[2] / "config" / "profiles"

    def __init__(self):
        self.rmods_info = self._open_yaml_file(self.RMODS_YAML)
        self.bbmods_smods_info = self._open_yaml_file(self.BBMODS_SMODS_YAML)

        self.iphy_info = self.get_iphy_file()
        self.available_profiles = self.get_tl_list()
        self.builds = None
        self.cus_ports = None

    def get_tl_list(self):
        not_supported_profiles = ('FCC', 'cloud_ho', 'MOON', 'CUS_CUS')
        return list(filter(
            lambda profile_path: not any(not_supported_profile in profile_path
                                     for not_supported_profile in not_supported_profiles),
            sorted(os.listdir(self.PROFILES_PATH))
        ))

    def get_iphy_file(self):
        with self.IPHY_XML.open() as f:
            return xmltodict.parse(f.read())

    # flake8: noqa: C901
    def run_yaml_generator(self, config, selected_profile):

        cus_profile = config.pop('selected_profile')
        enb_build = config.pop('selected_build')

        configuration = {}

        self._global_cell_counter = 0

        self._radio_to_cus_map = {}
        self._cus_to_mplane_only_map = {}

        enb_id = ""
        enb_yaml_to_parse = self._open_yaml_file(self.PROFILES_PATH / selected_profile / 'enb.yaml')
        referenced_enb_yaml = Config.get_config(enb_yaml_to_parse, enb_id, self.rmods_info, self.bbmods_smods_info)

        for enb_id, enb in config.items():
            self._radio_to_cus_map[enb_id] = {}

            ref_enb_key = f'enb{enb_id}'
            referenced_enb = referenced_enb_yaml[ref_enb_key]
            enb_params = self.get_basic_enb_params(referenced_enb)

            radios_params = self.get_radios_params(enb['rmods'], referenced_enb['radios'], enb_id)
            enb_params['radios'] = radios_params

            cells_params = self.get_cells_params(enb['cells'], referenced_enb['cells'], enb_id)
            enb_params['cells'] = cells_params

            bbmods_params = self.get_bbmods_params(enb['bbmods'])
            enb_params['bbmods'] = bbmods_params

            if 'smods' in enb:
                smods_type = enb['smods'].get(1, 'ASIA')
                smod_prod_code = self.bbmods_smods_info['SMODS'][smods_type]['prod_code_planned']
                enb_params['smods'] = {'1': {'prod_code_planned': smod_prod_code}}

            configuration[f'enb{enb_id}'] = enb_params

        ue_yaml_path = self.PROFILES_PATH / cus_profile / "ue.yaml"
        ue_params = self._open_yaml_file(ue_yaml_path)

        cus_to_mplane_only_map = {f'cus{cus_id}': mplane_list for cus_id, mplane_list in self._cus_to_mplane_only_map.items() if mplane_list}
        ue_params = dict(merge_dictionaries(cus_to_mplane_only_map, ue_params))

        epc_yaml_path = self.PROFILES_PATH / cus_profile / "epc.yaml"
        epc_params = self._open_yaml_file(epc_yaml_path)

        env_file_path = self.PROFILES_PATH.parent / "env.yaml"
        env_params = self._open_yaml_file(env_file_path)

        return configuration, ue_params, epc_params, env_params, enb_build, config[1]['smods'][1]

    def get_basic_enb_params(self, referenced_enb):
        enb_params = {}
        other_keys = {'smods', 'radios', 'bbmods', 'cells'}  # they are being set based on user configuration
        required_keys = list(set(referenced_enb.keys() - other_keys))
        for key in required_keys:
            enb_params[key] = referenced_enb[key]

        return enb_params

    def get_radios_params(self, rmods, referenced_rmods, enb_id):
        radios_params = {}
        for radio_id, radio in rmods.items():

            radio_params = {}
            #  {'AHFB': {1: ('ABIA (BBMOD-1)', 'RF1 (CUS1)')}, 'cus_port': ''}

            radio_type = next(iter(radio))
            radio_params["type"] = radio_type

            module, port = radio[radio_type][1]  # there is only single connection with key '1'
            module_name, module_type, module_id = re.search(r'(\S+) \(((?:BB|S)MOD)-(\d+)\)', module).group(1, 2, 3)
            port_id = int(re.search(r'RF(\d+)', port).group(1))
            cus_id = int(re.search(r'CUS(\d+)', port).group(1))
            self._cus_to_mplane_only_map[cus_id] = []
            self._radio_to_cus_map[enb_id][radio_id] = cus_id

            radio_params[module_type.lower()] = int(module_id)  # bbmod or smod
            radio_params["port"] = int(port_id)
            antenna_count = int(self.rmods_info[radio_type]['antenna_count'])
            radio_params["antennas"] = {"dc_voltage": ['OFF' for i in range(antenna_count)]}

            link_speed = self.rmods_info.get(radio_type, {}).get('link_speed')
            radio_params['link_speed'] = link_speed  # if?

            if module_name in ("ABIN", "ABIO", "ABIP", "ASOE", "ASOF", "ASOG", "ASOH"):
                protocol_type = self.rmods_info.get(radio_type, {}).get('protocol_type')
                radio_params["protocol_type"] = protocol_type  # if?
                if protocol_type == 'eCPRI':
                    radio_params['iq_compression'] = 'eCPRI IQ9_E7'

            if radio_id in referenced_rmods and 'second_endpoint_port_id' in referenced_rmods[radio_id]:
                radio_params['second_endpoint_port_id'] = referenced_rmods[radio_id]['second_endpoint_port_id']

            radios_params[radio_id] = radio_params
        return radios_params

    def get_cells_params(self, cells, referenced_cells, enb_id):
        cells_params = {}
        for cell_id, cell in cells.items():

            # cell default params -----------------------------------------------
            tac                       = "123"
            p_max                     = "370"
            dl_mimo_mode              = "Dynamic Open Loop MIMO"
            qrxlevminintra_f          = "-130"
            qrxlevmin                 = "-100"

            cell_params = {}

            cell_params['pci'] = int(cell_id)
            additional_cell_params = {}
            if 'tddFrameConf' in referenced_cells['1']:  # it should be only in LO testlines (CUS 2.0)
                additional_cell_params['tddFrameConf'] = referenced_cells['1']['tddFrameConf']

            if cell_id in referenced_cells:
                referenced_cell_params = referenced_cells[cell_id]
                tac = referenced_cell_params.get('tac', tac)
                p_max = referenced_cell_params.get('p_max', p_max)
                dl_mimo_mode = referenced_cell_params.get('dl_mimo_mode', dl_mimo_mode)
                qrxlevminintra_f = referenced_cell_params.get('qrxlevminintra_f', qrxlevminintra_f)
                qrxlevmin = referenced_cell_params.get('qrxlevmin', qrxlevmin)
                additional_cell_params['bbpool'] = referenced_cell_params.get('bbpool')

            cell_params['ch_bw'] = cell['ch_bw']
            if cell["cell_technology"] == "FDD":
                cell_params['earfcn_dl'] = cell['earfcn']
            else:
                cell_params['earfcn'] = cell['earfcn']

            cell_params['tac'] = tac
            cell_params['p_max'] = p_max
            cell_params['dl_mimo_mode'] = dl_mimo_mode
            cell_params['qrxlevminintra_f'] = qrxlevminintra_f
            cell_params['qrxlevmin'] = qrxlevmin

            additional_cell_params = {k: v for k, v in additional_cell_params.items() if v is not None}  # filter None Values
            cell_params = {**cell_params, **additional_cell_params}

            self._global_cell_counter += 1

            antennas_list, channels, cus_id = self.get_cells_connection_data(cell, enb_id)
            if cell.get('mplane_only') and isinstance(self._cus_to_mplane_only_map[cus_id], list):
                self._cus_to_mplane_only_map[cus_id].append(self._global_cell_counter)
            elif cell.get('mplane_only'):
                self._cus_to_mplane_only_map[cus_id] = [self._global_cell_counter]
            if antennas_list:
                cell_params['antennas'] = antennas_list
                cell_params['channels'] = channels
            cells_params[int(cell_id)] = cell_params

        return cells_params

    def get_cells_connection_data(self, cell, enb_id):
        antennas_list = []
        channels = []
        cus_id = None
        for _, connection in cell.items():
            if isinstance(connection, dict):
                rmod = connection.get('rmod')
                if rmod:
                    rmod_id = int(re.search(r'(\d+)', rmod).group(1))
                    cus_id = self._radio_to_cus_map[enb_id][rmod_id]
                    for antenna_id, (idx, antenna) in enumerate(
                            filter(lambda x: x[0] != 'rmod', connection.items())):
                        if antenna:
                            antennas_list.append(antenna_id)
                            if antenna == 'TXRX' or antenna == 'RXTX':
                                channels.extend([
                                    {
                                        'direction': 'TX',
                                        'radio': rmod_id,
                                        'port': int(idx)
                                    },
                                    {
                                        'direction': 'RX',
                                        'radio': rmod_id,
                                        'port': int(idx)
                                    }
                                ])
                            else:
                                channels.append({
                                    'direction': antenna,
                                    'radio': rmod_id,
                                    'port': int(idx)
                                })
        return (antennas_list, channels, cus_id)

    def get_bbmods_params(self, bbmods):
        bbmods_params = {}
        for bbmod_id, bbmod in bbmods.items():
            bbmod_params = {
                'prod_code_planned': self.bbmods_smods_info['BBMODS'][bbmod]['prod_code_planned'],
                'type': bbmod,
                'bb_card_usage': 2,
                'smod': 1,
                'port': int(bbmod_id)
            }
            bbmods_params[int(bbmod_id)] = bbmod_params
        return bbmods_params

    @staticmethod
    def _open_yaml_file(path):
        with open(path) as f:
            yaml_file = yaml.load(f, Loader=yaml.BaseLoader)
        return yaml_file
